(function (global) {
  "use strict";

  const recordSeparator = String.fromCharCode(0x1e);

  class HubConnection {
    constructor(url, options, reconnect) {
      this.url = url;
      this.options = options || {};
      this.reconnect = reconnect;
      this.handlers = {};
      this.socket = null;
      this.started = false;
      this.reconnectTimer = null;
    }

    on(target, handler) {
      this.handlers[target] = handler;
    }

    async start() {
      this.started = true;
      const token = await this._token();
      const negotiate = await this._negotiate(token);
      await this._connect(negotiate.connectionToken || negotiate.connectionId, token);
    }

    async stop() {
      this.started = false;
      if (this.reconnectTimer) {
        clearTimeout(this.reconnectTimer);
      }

      if (this.socket) {
        this.socket.close();
      }
    }

    async _token() {
      return this.options.accessTokenFactory ? await this.options.accessTokenFactory() : null;
    }

    async _negotiate(token) {
      const response = await fetch(this.url.replace(/\/$/, "") + "/negotiate?negotiateVersion=1", {
        method: "POST",
        mode: "cors",
        headers: token ? { Authorization: "Bearer " + token } : {}
      });

      if (!response.ok) {
        throw new Error("SignalR negotiate isteği başarısız oldu.");
      }

      return await response.json();
    }

    _connect(connectionToken, token) {
      return new Promise((resolve, reject) => {
        const websocketUrl = this._websocketUrl(connectionToken, token);
        const socket = new WebSocket(websocketUrl);
        let opened = false;

        socket.onopen = () => {
          opened = true;
          this.socket = socket;
          socket.send(JSON.stringify({ protocol: "json", version: 1 }) + recordSeparator);
          resolve();
        };

        socket.onerror = () => {
          if (!opened) {
            reject(new Error("SignalR WebSocket bağlantısı kurulamadı."));
          }
        };

        socket.onmessage = event => this._receive(event.data);
        socket.onclose = () => this._closed();
      });
    }

    _websocketUrl(connectionToken, token) {
      const hubUrl = new URL(this.url, window.location.origin);
      hubUrl.protocol = hubUrl.protocol === "https:" ? "wss:" : "ws:";
      hubUrl.searchParams.set("id", connectionToken);

      if (token) {
        hubUrl.searchParams.set("access_token", token);
      }

      return hubUrl.toString();
    }

    _receive(data) {
      const messages = String(data).split(recordSeparator).filter(Boolean);
      for (const rawMessage of messages) {
        const message = JSON.parse(rawMessage);
        if (message.type === 1 && message.target && this.handlers[message.target]) {
          this.handlers[message.target].apply(null, message.arguments || []);
        }
      }
    }

    _closed() {
      this.socket = null;
      if (!this.started || !this.reconnect) {
        return;
      }

      this.reconnectTimer = setTimeout(() => {
        this.start().catch(() => this._closed());
      }, 5000);
    }
  }

  class HubConnectionBuilder {
    constructor() {
      this.url = null;
      this.options = {};
      this.reconnect = false;
    }

    withUrl(url, options) {
      this.url = url;
      this.options = options || {};
      return this;
    }

    withAutomaticReconnect() {
      this.reconnect = true;
      return this;
    }

    build() {
      return new HubConnection(this.url, this.options, this.reconnect);
    }
  }

  global.signalR = {
    HubConnectionBuilder
  };
})(window);
